SELECT 
  FROM tc_model_workflow
 WHERE model_key = #{modelKey}
   AND workflow_name = #{workflowName}
   AND message_name = #{messageName}

SELECT FROM tc_model_workflow
AND model_key = #{modelKey}
AND workflow_name LIKE CONCAT('%', #{workflowNameLike}, '%')
AND message_name LIKE CONCAT('%', #{messageNameLike}, '%')
ORDER BY workflow_key DESC
LIMIT #{limit} OFFSET #{offset}
